{
  "items": [
    {
      "name": "PiLp.nndist_eq_of_L1",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_2} {β : ι → Type u_4} [inst : Fintype ι] [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)]\n  (x y : PiLp 1 β), nndist x y = ∑ i, nndist (x.ofLp i) (y.ofLp i)"
    },
    {
      "name": "PiLp.dist_toLp_single_same",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ (p : ENNReal) {ι : Type u_2} (β : ι → Type u_4) [hp : Fact (1 ≤ p)] [inst : Fintype ι]\n  [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)] [inst_2 : DecidableEq ι] (i : ι) (b₁ b₂ : β i),\n  dist (WithLp.toLp p (Pi.single i b₁)) (WithLp.toLp p (Pi.single i b₂)) = dist b₁ b₂"
    },
    {
      "name": "WithLp.prod_edist_eq_of_L1",
      "module_name": "Mathlib.Analysis.Normed.Lp.ProdLp",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SeminormedAddCommGroup α] [inst_1 : SeminormedAddCommGroup β]\n  (x y : WithLp 1 (α × β)), edist x y = edist x.fst y.fst + edist x.snd y.snd"
    },
    {
      "name": "MeasureTheory.Lp.dist_eq_norm",
      "module_name": "Mathlib.MeasureTheory.Function.LpSpace.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {E : Type u_4} {m : MeasurableSpace α} {p : ENNReal} {μ : MeasureTheory.Measure α}\n  [inst : NormedAddCommGroup E] (f g : ↥(MeasureTheory.Lp E p μ)), dist f g = ‖f - g‖"
    },
    {
      "name": "PiLp.pseudoMetricAux",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "abbrev",
      "type": "(p : ENNReal) →\n  {ι : Type u_2} →\n    (α : ι → Type u_3) →\n      [Fact (1 ≤ p)] → [(i : ι) → PseudoMetricSpace (α i)] → [Fintype ι] → PseudoMetricSpace (PiLp p α)"
    },
    {
      "name": "PiLp.edist_eq_of_L1",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_2} {β : ι → Type u_4} [inst : Fintype ι] [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)]\n  (x y : PiLp 1 β), edist x y = ∑ i, edist (x.ofLp i) (y.ofLp i)"
    },
    {
      "name": "PiLp.dist_eq_of_L1",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_2} {β : ι → Type u_4} [inst : Fintype ι] [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)]\n  (x y : PiLp 1 β), dist x y = ∑ i, dist (x.ofLp i) (y.ofLp i)"
    }
  ]
}
